		&XMLWhenFilterLoading;
		&XMLWhenFilterClosing;
		
		
			
				

select @ngay_dh1 as ngay_dh1, @ngay_dh2 as ngay_dh2, @ngay_bc1 as ngay_bc1, @ngay_bc2 as ngay_bc, @ma_px as ma_px, @$ten_px as ten_px
exec zrpt_286 @ma_px, @ngay_dh1, @ngay_dh2, @ngay_bc1, @ngay_bc2, @ma_kh, @ma_vt, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._hiddenForms = [];
			g._alterTitle = [null, [
				['%s0', f.getItemValue('ma_px') + '-' + f.getItemValue('ten_px%l'), true],
				['%s1', f.getItem('ngay_dh1').value, true], 
				['%s2', f.getItem('ngay_dh2').value, true],
				['%s3', f.getItem('ngay_bc1').value, true],
				['%s4', f.getItem('ngay_bc2').value, true]
			]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

		
	

	&OutlineCss;
